class NumArray {
    vector<int> tree;
    int n;
    void buildTree(const vector<int>& nums, int node, int start, int end) {
        if (start == end) {
            tree[node] = nums[start];
        } else {
            int mid = start + (end - start) / 2;
            buildTree(nums, 2 * node, start, mid);
            buildTree(nums, 2 * node + 1, mid + 1, end);
            tree[node] = tree[2 * node] + tree[2 * node + 1];
        }
    }
public:
    NumArray(vector<int>& nums) {
        n = nums.size();
        tree.resize(4 * n, 0);
        if (n > 0) buildTree(nums, 1, 0, n - 1);
    }
    void update(int index, int val, int node, int start, int end) {
        if (start == end) {
            tree[node] = val;
            return;
        }
        int mid = start + (end - start) / 2;
        if (index <= mid) update(index, val, 2 * node, start, mid);
        else update(index, val, 2 * node + 1, mid + 1, end);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }
    int sumRange(int left, int right, int node, int start, int end) {
        if (left <= start && end <= right) return tree[node];
        int mid = start + (end - start) / 2;
        int sum = 0;
        if (left <= mid) sum += sumRange(left, right, 2 * node, start, mid);
        if (right > mid) sum += sumRange(left, right, 2 * node + 1, mid + 1, end);
        return sum;
    }
};

