using namespace std;
struct Fenwick {
    int n;
    vector<int> bit;
    Fenwick(int n) : n(n), bit(n + 1, 0) {}
    void add(int idx, int val) {
        for (; idx <= n; idx += idx & -idx)
            bit[idx] += val;
    }
    int query(int idx) {
        int sum = 0;
        for (; idx > 0; idx -= idx & -idx)
            sum += bit[idx];
        return sum;
    }
};
class Solution {
public:
    int countInversions(vector<int>& nums) {
        int n = nums.size();
        Fenwick ft(n);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans += ft.query(n) - ft.query(nums[i]);
            ft.add(nums[i], 1);
        }
        return ans;
    }
};

class Solution {
    static class Fenwick {
        int n;
        int[] bit;
        Fenwick(int n) {
            this.n = n;
            bit = new int[n + 1];
        }
        void add(int idx, int val) {
            for (; idx <= n; idx += idx & -idx)
                bit[idx] += val;
        }
        int query(int idx) {
            int sum = 0;
            for (; idx > 0; idx -= idx & -idx)
                sum += bit[idx];
            return sum;
        }
    }
    public int countInversions(int[] nums) {
        int n = nums.length;
        Fenwick ft = new Fenwick(n);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans += ft.query(n) - ft.query(nums[i]);
            ft.add(nums[i], 1);
        }
        return ans;
    }
}

