#include <vector>
using namespace std;
class Solution {
public:
    string minWindow(string s, string t) {
        vector<int> target(128, 0);
        for (char c : t) target[c]++;
        int required = t.size();
        int left = 0, right = 0;
        int min_len = 1e9, start_idx = 0;
        while (right < s.size()) {
            if (target[s[right]] > 0) required--;
            target[s[right]]--;
            right++;
            while (required == 0) {
                if (right - left < min_len) {
                    min_len = right - left;
                    start_idx = left;
                }
                target[s[left]]++;
                if (target[s[left]] > 0) required++;
                left++;
            }
        }
        return min_len == 1e9 ? "" : s.substr(start_idx, min_len);
    }
};

class Solution {
    public String minWindow(String s, String t) {
        int[] target = new int[128];
        for (char c : t.toCharArray()) target[c]++;
        int required = t.length();
        int left = 0, right = 0;
        int minLen = 1000000000, startIdx = 0;
        while (right < s.length()) {
            char c = s.charAt(right);
            if (target[c] > 0) required--;
            target[c]++;
            right++;
            while (required == 0) {
                if (right - left < minLen) {
                    minLen = right - left;
                    startIdx = left;
                }
                char lc = s.charAt(left);
                target[lc]++;
                if (target[lc] > 0) required++;
                left++;
            }
        }
        return minLen == 1000000000 ? "" : s.substring(startIdx, startIdx + minLen);
    }
}

