class TreeAncestor {
    vector<vector<int>> up;
public:
    TreeAncestor(int n, vector<int>& parent) {
        up.assign(n, vector<int>(20, -1));
        for (int i = 0; i < n; i++) {
            up[i][0] = parent[i];
        }
        for (int j = 1; j < 20; j++) {
            for (int i = 0; i < n; i++) {
                if (up[i][j - 1] != -1) {
                    up[i][j] = up[up[i][j - 1]][j - 1];
                }
            }
        }
    }
    int getKthAncestor(int node, int k) {
        for (int j = 0; j < 20; j++) {
            if ((k >> j) & 1) {
                node = up[node][j];
                if (node == -1) break;
            }
        }
        return node;
    }
};

class TreeAncestor {
