        bool is_word = false;
    };
    Node* root;
public:
    Trie() { root = new Node(); }
    void insert(string word) {
        Node* curr = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!curr->child[idx]) curr->child[idx] = new Node();
            curr = curr->child[idx];
        }
        curr->is_word = true;
    }
    bool search(string word) {
        Node* curr = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!curr->child[idx]) return false;
            curr = curr->child[idx];
        }
        return curr->is_word;
    }
};

