            while (i + z[i] < n && s.charAt(z[i]) == s.charAt(i + z[i])) z[i]++;
            if (i + z[i] - 1 > r) {
                l = i;
                r = i + z[i] - 1;
            }
        }
        return z;
    }
}

#include <string>
using namespace std;
class Solution {
public:
    int rabinKarp(string s, string p) {
        long long mod = 1e9 + 7, base = 31;
        long long p_hash = 0, s_hash = 0, power = 1;
        int m = p.size(), n = s.size();
        for (int i = 0; i < m; i++) {
            p_hash = (p_hash * base + p[i]) % mod;
            s_hash = (s_hash * base + s[i]) % mod;
            if (i > 0) power = (power * base) % mod;
        }
        for (int i = 0; i <= n - m; i++) {
            if (p_hash == s_hash && s.substr(i, m) == p) return i;
            if (i < n - m) {
                s_hash = ((s_hash - s[i] * power % mod + mod) * base + s[i + m]) % mod;
            }
        }
        return -1;
    }
};

class Solution {
    public int rabinKarp(String s, String p) {
        long mod = 1000000007, base = 31;
        long pHash = 0, sHash = 0, power = 1;
        int m = p.length(), n = s.length();
        for (int i = 0; i < m; i++) {
            pHash = (pHash * base + p.charAt(i)) % mod;
            sHash = (sHash * base + s.charAt(i)) % mod;
            if (i > 0) power = (power * base) % mod;
        }
        for (int i = 0; i <= n - m; i++) {
            if (pHash == sHash && s.substring(i, i + m).equals(p)) return i;
            if (i < n - m) {
                sHash = ((sHash - s.charAt(i) * power % mod + mod) * base + s.charAt(i + m)) % mod;
            }
        }
        return -1;
    }
}

