import java.util.*;
class Solution {
    public int flipLights(int n, int k) {
        n = Math.min(6, n);
        Set<String> set = new HashSet<>();
        set.add("1".repeat(n));
        for(int i = 0; i < k; ++i){
            Set<String> temp = new HashSet<>();
            for(String s: set){
                StringBuilder x = new StringBuilder(s);
                for(int j = 0; j < n; ++j){
                    if(x.charAt(j) == '0') x.setCharAt(j, '1');
                    else x.setCharAt(j, '0');
                }
                temp.add(x.toString());
                x = new StringBuilder(s);
                for(int j = 0; j < n; j += 2){
                    if(x.charAt(j) == '0') x.setCharAt(j, '1');
                    else x.setCharAt(j, '0');
                }
                temp.add(x.toString());
            }
            set = temp;
        }
        return set.size();
    }
}

