#include <vector>
#include <deque>
using namespace std;
class Solution {
public:
    int minCost(vector<vector<pair<int, int>>>& adj, int n, int src, int dst) {
        vector<int> dist(n, 1e9);
        deque<int> dq;
        dist[src] = 0;
        dq.push_back(src);
        while (!dq.empty()) {
            int u = dq.front();
            dq.pop_front();
            for (auto& edge : adj[u]) {
                int v = edge.first, w = edge.second;
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    if (w == 1) dq.push_back(v);
                    else dq.push_front(v);
                }
            }
        }
        return dist[dst] == 1e9 ? -1 : dist[dst];
    }
};

import java.util.*;
class Solution {
    public int minCost(List<List<int[]>> adj, int n, int src, int dst) {
        int[] dist = new int[n];
        Arrays.fill(dist, 1000000000);
        Deque<Integer> dq = new ArrayDeque<>();
        dist[src] = 0;
        dq.addLast(src);
        while (!dq.isEmpty()) {
            int u = dq.pollFirst();
            for (int[] edge : adj.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    if (w == 1) dq.addLast(v);
                    else dq.addFirst(v);
                }
            }
        }
        return dist[dst] == 1000000000 ? -1 : dist[dst];
    }
}

