#include <algorithm>
using namespace std;
struct TrieNode {
    TrieNode* child[2] = {nullptr, nullptr};
};
class Solution {
    TrieNode* root = new TrieNode();
    void insert(int num) {
        TrieNode* cur = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (!cur->child[bit]) cur->child[bit] = new TrieNode();
            cur = cur->child[bit];
        }
    }
    int query(int num) {
        TrieNode* cur = root;
        int max_xor = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (cur->child[1 - bit]) {
                max_xor |= (1 << i);
                cur = cur->child[1 - bit];
            } else {
                cur = cur->child[bit];
            }
        }
        return max_xor;
    }
public:
    int findMaximumXOR(vector<int>& nums) {
        for (int x : nums) insert(x);
        int ans = 0;
        for (int x : nums) ans = max(ans, query(x));
        return ans;
    }
};

