        for (char c : p.toCharArray()) pCnt[c - 'a']++;
        int k = p.length();
        for (int i = 0; i < k; i++) sCnt[s.charAt(i) - 'a']++;
        if (Arrays.equals(sCnt, pCnt)) res.add(0);
        for (int i = k; i < s.length(); i++) {
            sCnt[s.charAt(i) - 'a']++;
            sCnt[s.charAt(i - k) - 'a']--;
            if (Arrays.equals(sCnt, pCnt)) res.add(i - k + 1);
        }
        return res;
    }
}

