        }
        for (int i = 0; i < minutes; i++) {
            if (grumpy[i] == 1) extra += customers[i];
        }
        int maxExtra = extra;
        for (int i = minutes; i < n; i++) {
            if (grumpy[i] == 1) extra += customers[i];
            if (grumpy[i - minutes] == 1) extra -= customers[i - minutes];
            maxExtra = Math.max(maxExtra, extra);
        }
