        unordered_map<int, int> next_gr;
        stack<int> st;
        for (int x : nums2) {
            while (!st.empty() && st.top() < x) {
                next_gr[st.top()] = x;
                st.pop();
            }
            st.push(x);
        }
        vector<int> res;
        for (int x : nums1) {
            res.push_back(next_gr.count(x) ? next_gr[x] : -1);
        }
        return res;
    }
