#include <algorithm>
using namespace std;
class Solution {
    int largestRectangleArea(vector<int>& heights) {
        heights.push_back(0);
        stack<int> st;
        int max_a = 0;
        for (int i = 0; i < heights.size(); i++) {
            while (!st.empty() && heights[st.top()] >= heights[i]) {
                int h = heights[st.top()]; st.pop();
                int w = st.empty() ? i : i - st.top() - 1;
                max_a = max(max_a, h * w);
            }
            st.push(i);
        }
        heights.pop_back();
        return max_a;
    }
public:
    int maximalRectangle(vector<vector<char>>& matrix) {
        if (matrix.empty()) return 0;
        int m = matrix.size(), n = matrix[0].size(), ans = 0;
        vector<int> heights(n, 0);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == '1') heights[j]++;
                else heights[j] = 0;
            }
            ans = max(ans, largestRectangleArea(heights));
        }
        return ans;
    }
};

import java.util.*;
class Solution {
    int largestRectangleArea(int[] heights) {
        int[] h = new int[heights.length + 1];
        System.arraycopy(heights, 0, h, 0, heights.length);
        Deque<Integer> st = new ArrayDeque<>();
        int maxA = 0;
        for (int i = 0; i < h.length; i++) {
            while (!st.isEmpty() && h[st.peek()] >= h[i]) {
                int curH = h[st.pop()];
                int w = st.isEmpty() ? i : i - st.peek() - 1;
                maxA = Math.max(maxA, curH * w);
            }
            st.push(i);
        }
        return maxA;
    }
    public int maximalRectangle(char[][] matrix) {
        if (matrix.length == 0) return 0;
        int m = matrix.length, n = matrix[0].length, ans = 0;
        int[] heights = new int[n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == '1') heights[j]++;
                else heights[j] = 0;
            }
            ans = Math.max(ans, largestRectangleArea(heights));
        }
        return ans;
    }
}

#include <vector>
#include <stack>
using namespace std;
class Solution {
public:
    int sumSubarrayMins(vector<int>& arr) {
        int n = arr.size(), mod = 1e9 + 7;
        vector<int> ple(n), nle(n);
        stack<int> s1, s2;
        for (int i = 0; i < n; i++) {
            while (!s1.empty() && arr[s1.top()] > arr[i]) s1.pop();
            ple[i] = s1.empty() ? -1 : s1.top();
            s1.push(i);
        }
        for (int i = n - 1; i >= 0; i--) {
            while (!s2.empty() && arr[s2.top()] >= arr[i]) s2.pop();
            nle[i] = s2.empty() ? n : s2.top();
            s2.push(i);
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            long long left = i - ple[i], right = nle[i] - i;
            ans = (ans + (left * right % mod) * arr[i]) % mod;
        }
        return ans;
    }
};

import java.util.*;
class Solution {
    public int sumSubarrayMins(int[] arr) {
        int n = arr.length, mod = 1000000007;
        int[] ple = new int[n], nle = new int[n];
        Deque<Integer> s1 = new ArrayDeque<>(), s2 = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            while (!s1.isEmpty() && arr[s1.peek()] > arr[i]) s1.pop();
            ple[i] = s1.isEmpty() ? -1 : s1.peek();
            s1.push(i);
        }
        for (int i = n - 1; i >= 0; i--) {
            while (!s2.isEmpty() && arr[s2.peek()] >= arr[i]) s2.pop();
            nle[i] = s2.isEmpty() ? n : s2.peek();
            s2.push(i);
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            long left = i - ple[i], right = nle[i] - i;
            ans = (ans + (left * right % mod) * arr[i]) % mod;
        }
        return (int)ans;
    }
}

