class Solution {
public:
    vector<int> asteroidCollision(vector<int>& asteroids) {
        vector<int> st;
        for (int ast : asteroids) {
            bool alive = true;
            while (alive && ast < 0 && !st.empty() && st.back() > 0) {
                if (st.back() < -ast) { st.pop_back(); continue; }
                else if (st.back() == -ast) { st.pop_back(); }
