        }
        return res;
    }
}

#include <string>
#include <vector>
#include <queue>
#include <unordered_map>
using namespace std;
class Solution {
public:
    string reorganizeString(string s) {
        unordered_map<char, int> count;
        for (char c : s) count[c]++;
        priority_queue<pair<int, char>> pq;
        for (auto& p : count) pq.push({p.second, p.first});
        string res = "";
        pair<int, char> prev = {0, '#'};
        while (!pq.empty()) {
            auto curr = pq.top();
            pq.pop();
            res += curr.second;
            if (prev.first > 0) pq.push(prev);
            curr.first--;
            prev = curr;
        }
        return res.length() == s.length() ? res : "";
    }
};

import java.util.*;
class Solution {
    public String reorganizeString(String s) {
        Map<Character, Integer> count = new HashMap<>();
        for (char c : s.toCharArray()) count.put(c, count.getOrDefault(c, 0) + 1);
        PriorityQueue<Character> pq = new PriorityQueue<>((a, b) -> count.get(b) - count.get(a));
        pq.addAll(count.keySet());
        StringBuilder res = new StringBuilder();
        while (pq.size() >= 2) {
            char c1 = pq.poll();
            char c2 = pq.poll();
            res.append(c1).append(c2);
            count.put(c1, count.get(c1) - 1);
            count.put(c2, count.get(c2) - 1);
            if (count.get(c1) > 0) pq.offer(c1);
            if (count.get(c2) > 0) pq.offer(c2);
        }
        if (!pq.isEmpty()) {
            char c = pq.poll();
            if (count.get(c) > 1) return "";
            res.append(c);
        }
        return res.toString();
    }
}

#include <vector>
#include <queue>
#include <unordered_map>
using namespace std;
class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        unordered_map<char, int> count;
        for (char c : tasks) count[c]++;
        priority_queue<int> pq;
        for (auto& p : count) pq.push(p.second);
        int time = 0;
        while (!pq.empty()) {
            vector<int> temp;
            int cycle = n + 1;
            while (cycle > 0 && !pq.empty()) {
                int top = pq.top();
                pq.pop();
                if (top > 1) temp.push_back(top - 1);
                time++;
                cycle--;
            }
            for (int x : temp) pq.push(x);
            if (pq.empty()) break;
            time += cycle;
        }
        return time;
    }
};

import java.util.*;
class Solution {
    public int leastInterval(char[] tasks, int n) {
        Map<Character, Integer> count = new HashMap<>();
        for (char c : tasks) count.put(c, count.getOrDefault(c, 0) + 1);
        PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
        pq.addAll(count.values());
        int time = 0;
        while (!pq.isEmpty()) {
            List<Integer> temp = new ArrayList<>();
            int cycle = n + 1;
            while (cycle > 0 && !pq.isEmpty()) {
                int top = pq.poll();
                if (top > 1) temp.add(top - 1);
                time++;
                cycle--;
            }
            pq.addAll(temp);
            if (pq.isEmpty()) break;
            time += cycle;
        }
        return time;
    }
}

