                            grid[nr][nc] = 1;
                            q.offer(new int[]{nr, nc});
                        }
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

#include <vector>
#include <string>
#include <queue>
#include <unordered_set>
using namespace std;
class Solution {
public:
    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {
        unordered_set<string> dict(wordList.begin(), wordList.end());
        if (!dict.count(endWord)) return 0;
        queue<string> q;
        q.push(beginWord);
        int steps = 1;
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                string w = q.front();
                q.pop();
                if (w == endWord) return steps;
                for (int i = 0; i < (int)w.size(); i++) {
                    char orig = w[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        w[i] = c;
                        if (dict.count(w)) {
                            dict.erase(w);
                            q.push(w);
                        }
                    }
                    w[i] = orig;
                }
            }
            steps++;
        }
        return 0;
    }
};

