            while (sz-- > 0) {
                String w = q.poll();
                if (w.equals(endWord)) return steps;
                char[] chs = w.toCharArray();
                for (int i = 0; i < chs.length; i++) {
                    char orig = chs[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        chs[i] = c;
                        String next = new String(chs);
                        if (dict.contains(next)) {
                            dict.remove(next);
                            q.offer(next);
                        }
                    }
                    chs[i] = orig;
                }
            }
            steps++;
        }
        return 0;
    }
}

#include <vector>
#include <string>
#include <queue>
#include <unordered_set>
using namespace std;
class Solution {
public:
    int openLock(vector<string>& deadends, string target) {
        unordered_set<string> dead(deadends.begin(), deadends.end());
        if (dead.count("0000")) return -1;
        queue<string> q;
        q.push("0000");
        dead.insert("0000");
        int steps = 0;
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                string curr = q.front();
                q.pop();
                if (curr == target) return steps;
                for (int i = 0; i < 4; i++) {
                    for (int d = -1; d <= 1; d += 2) {
                        string next = curr;
                        next[i] = (next[i] - '0' + d + 10) % 10 + '0';
                        if (!dead.count(next)) {
                            dead.insert(next);
                            q.push(next);
                        }
                    }
                }
            }
            steps++;
        }
        return -1;
    }
};

