            int sz = q.size();
            while (sz--) {
                TreeNode* node = q.front();
                q.pop();
                if (!node->left && !node->right) return depth;
                if (node->left) q.push(node->left);
                if (node->right) q.push(node->right);
            }
            depth++;
        }
        return depth;
    }
};

import java.util.*;
class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int x) { val = x; }
}
class Solution {
    public int minDepth(TreeNode root) {
        if (root == null) return 0;
        Queue<TreeNode> q = new LinkedList<>();
        q.offer(root);
        int depth = 1;
        while (!q.isEmpty()) {
            int sz = q.size();
            while (sz-- > 0) {
                TreeNode node = q.poll();
                if (node.left == null && node.right == null) return depth;
                if (node.left != null) q.offer(node.left);
                if (node.right != null) q.offer(node.right);
            }
            depth++;
        }
        return depth;
    }
}

#include <vector>
#include <queue>
#include <unordered_map>
#include <unordered_set>
using namespace std;
class Solution {
public:
    int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {
        if (source == target) return 0;
        unordered_map<int, vector<int>> stop_to_routes;
        for (int i = 0; i < (int)routes.size(); i++) {
            for (int stop : routes[i]) stop_to_routes[stop].push_back(i);
        }
        queue<int> q;
        unordered_set<int> visited_routes;
        q.push(source);
        int buses = 0;
        while (!q.empty()) {
            int sz = q.size();
            buses++;
            while (sz--) {
                int stop = q.front();
                q.pop();
                for (int r : stop_to_routes[stop]) {
                    if (visited_routes.count(r)) continue;
                    visited_routes.insert(r);
                    for (int next_stop : routes[r]) {
                        if (next_stop == target) return buses;
                        q.push(next_stop);
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;
class Solution {
    public int numBusesToDestination(int[][] routes, int source, int target) {
