        Map<Integer, List<Integer>> stopToRoutes = new HashMap<>();
        for (int i = 0; i < routes.length; i++) {
            for (int stop : routes[i]) {
                stopToRoutes.computeIfAbsent(stop, k -> new ArrayList<>()).add(i);
            }
        }
        Queue<Integer> q = new LinkedList<>();
        Set<Integer> visitedRoutes = new HashSet<>();
        q.offer(source);
        int buses = 0;
        while (!q.isEmpty()) {
            int sz = q.size();
            buses++;
            while (sz-- > 0) {
                int stop = q.poll();
                for (int r : stopToRoutes.getOrDefault(stop, Collections.emptyList())) {
                    if (visitedRoutes.contains(r)) continue;
                    visitedRoutes.add(r);
                    for (int nextStop : routes[r]) {
                        if (nextStop == target) return buses;
                        q.offer(nextStop);
                    }
                }
            }
        }
        return -1;
    }
}

#include <vector>
#include <queue>
using namespace std;
class Solution {
public:
    int snakesAndLadders(vector<vector<int>>& board) {
        int n = board.size();
        auto get_pos = [&](int s) -> pair<int, int> {
            int r = (s - 1) / n;
            int c = (s - 1) % n;
            if (r % 2 == 1) c = n - 1 - c;
            return {n - 1 - r, c};
        };
        vector<int> dist(n * n + 1, -1);
        queue<int> q;
        q.push(1);
        dist[1] = 0;
        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            if (curr == n * n) return dist[curr];
            for (int i = 1; i <= 6 && curr + i <= n * n; i++) {
                int next = curr + i;
                auto [r, c] = get_pos(next);
                if (board[r][c] != -1) next = board[r][c];
                if (dist[next] == -1) {
                    dist[next] = dist[curr] + 1;
                    q.push(next);
                }
            }
        }
        return -1;
    }
};

