#include <vector>
#include <string>
#include <queue>
#include <unordered_set>
using namespace std;
class Solution {
public:
    int minMutation(string startGene, string endGene, vector<string>& bank) {
        unordered_set<string> valid(bank.begin(), bank.end());
        if (!valid.count(endGene)) return -1;
        queue<string> q;
        q.push(startGene);
        int steps = 0;
        char genes[] = {'A', 'C', 'G', 'T'};
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                string curr = q.front();
                q.pop();
                if (curr == endGene) return steps;
                for (int i = 0; i < 8; i++) {
                    char orig = curr[i];
                    for (char g : genes) {
                        curr[i] = g;
                        if (valid.count(curr)) {
                            valid.erase(curr);
                            q.push(curr);
                        }
                    }
                    curr[i] = orig;
                }
            }
            steps++;
        }
        return -1;
    }
};

import java.util.*;
class Solution {
    public int minMutation(String startGene, String endGene, String[] bank) {
        Set<String> valid = new HashSet<>(Arrays.asList(bank));
        if (!valid.contains(endGene)) return -1;
        Queue<String> q = new LinkedList<>();
        q.offer(startGene);
        int steps = 0;
        char[] genes = new char[]{'A', 'C', 'G', 'T'};
        while (!q.isEmpty()) {
            int sz = q.size();
            while (sz-- > 0) {
                String curr = q.poll();
                if (curr.equals(endGene)) return steps;
                char[] chs = curr.toCharArray();
                for (int i = 0; i < 8; i++) {
                    char orig = chs[i];
                    for (char g : genes) {
                        chs[i] = g;
                        String next = new String(chs);
                        if (valid.contains(next)) {
                            valid.remove(next);
                            q.offer(next);
                        }
                    }
                    chs[i] = orig;
                }
            }
            steps++;
        }
        return -1;
    }
}

#include <vector>
#include <queue>
using namespace std;
class Solution {
public:
    int orangesRotting(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        queue<pair<int, int>> q;
        int fresh = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 2) q.push({i, j});
                else if (grid[i][j] == 1) fresh++;
            }
        }
        int minutes = 0;
        int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        while (!q.empty() && fresh > 0) {
            int sz = q.size();
            while (sz--) {
                auto [r, c] = q.front();
                q.pop();
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == 1) {
                        grid[nr][nc] = 2;
                        fresh--;
                        q.push({nr, nc});
                    }
                }
            }
            minutes++;
        }
        return fresh == 0 ? minutes : -1;
    }
};

