#include <vector>
#include <string>
#include <queue>
#include <unordered_map>
#include <unordered_set>
using namespace std;
class Solution {
public:
    string alienOrder(vector<string>& words) {
        unordered_map<char, unordered_set<char>> adj;
        unordered_map<char, int> in_degree;
        for (auto& w : words) for (char c : w) in_degree[c] = 0;
        for (int i = 0; i < (int)words.size() - 1; i++) {
            string w1 = words[i], w2 = words[i + 1];
            int len = min(w1.size(), w2.size());
            bool diff = false;
            for (int j = 0; j < len; j++) {
                if (w1[j] != w2[j]) {
                    if (!adj[w1[j]].count(w2[j])) {
                        adj[w1[j]].insert(w2[j]);
                        in_degree[w2[j]]++;
                    }
                    diff = true;
                    break;
                }
            }
            if (!diff && w1.size() > w2.size()) return "";
        }
        queue<char> q;
        for (auto& p : in_degree) if (p.second == 0) q.push(p.first);
        string res = "";
        while (!q.empty()) {
            char u = q.front();
            q.pop();
            res += u;
            for (char v : adj[u]) {
                in_degree[v]--;
                if (in_degree[v] == 0) q.push(v);
            }
        }
        return res.size() == in_degree.size() ? res : "";
    }
};

import java.util.*;
class Solution {
    public String alienOrder(String[] words) {
        Map<Character, Set<Character>> adj = new HashMap<>();
        Map<Character, Integer> inDegree = new HashMap<>();
        for (String w : words) for (char c : w.toCharArray()) inDegree.put(c, 0);
        for (int i = 0; i < words.length - 1; i++) {
            String w1 = words[i], w2 = words[i + 1];
            int len = Math.min(w1.length(), w2.length());
            boolean diff = false;
            for (int j = 0; j < len; j++) {
                if (w1.charAt(j) != w2.charAt(j)) {
                    adj.computeIfAbsent(w1.charAt(j), k -> new HashSet<>());
                    if (adj.get(w1.charAt(j)).add(w2.charAt(j))) {
                        inDegree.put(w2.charAt(j), inDegree.get(w2.charAt(j)) + 1);
                    }
                    diff = true;
                    break;
                }
            }
            if (!diff && w1.length() > w2.length()) return "";
        }
        Queue<Character> q = new LinkedList<>();
        for (char c : inDegree.keySet()) if (inDegree.get(c) == 0) q.offer(c);
        StringBuilder res = new StringBuilder();
        while (!q.isEmpty()) {
            char u = q.poll();
            res.append(u);
            for (char v : adj.getOrDefault(u, Collections.emptySet())) {
                inDegree.put(v, inDegree.get(v) - 1);
                if (inDegree.get(v) == 0) q.offer(v);
            }
        }
        return res.length() == inDegree.size() ? res.toString() : "";
    }
}

#include <vector>
#include <queue>
using namespace std;
class Solution {
public:
    vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges) {
        if (n == 1) return {0};
        vector<vector<int>> adj(n);
        vector<int> in_degree(n, 0);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
            in_degree[e[0]]++;
            in_degree[e[1]]++;
        }
        queue<int> q;
        for (int i = 0; i < n; i++) if (in_degree[i] == 1) q.push(i);
        int remaining = n;
        while (remaining > 2) {
            int sz = q.size();
            remaining -= sz;
            while (sz--) {
                int u = q.front();
                q.pop();
                for (int v : adj[u]) {
                    in_degree[v]--;
                    if (in_degree[v] == 1) q.push(v);
                }
            }
        }
        vector<int> res;
        while (!q.empty()) {
            res.push_back(q.front());
            q.pop();
        }
        return res;
    }
};

