        pq.push({0, src, 0});
        while (!pq.empty()) {
            auto curr = pq.top();
            pq.pop();
            int cost = curr[0], u = curr[1], stops = curr[2];
            if (u == dst) return cost;
            if (stops > k) continue;
            for (auto& [v, weight] : adj[u]) {
                if (cost + weight < dist[v]) {
                    dist[v] = cost + weight;
                    pq.push({cost + weight, v, stops + 1});
                }
            }
        }
        return -1;
    }
};

