            res.push_back(path);
            return;
        }
        if (open < n) dfs(open + 1, close, n, path + "(");
        if (close < open) dfs(open, close + 1, n, path + ")");
    }
public:
    vector<string> generateParenthesis(int n) {
        dfs(0, 0, n, "");
        return res;
    }
};

