        if (path.length() == 2 * n) {
            res.add(path.toString());
            return;
        }
        if (open < n) {
            path.append("(");
            dfs(open + 1, close, n, path);
            path.deleteCharAt(path.length() - 1);
        }
        if (close < open) {
            path.append(")");
            dfs(open, close + 1, n, path);
            path.deleteCharAt(path.length() - 1);
        }
    }
