class Solution {
public:
    double myPow(double x, int n) {
        long long N = n;
        if (N < 0) {
            x = 1 / x;
            N = -N;
        }
        double ans = 1;
        double current_product = x;
        while (N > 0) {
            if (N % 2 == 1) ans *= current_product;
            current_product *= current_product;
            N >>= 1;
        }
        return ans;
    }
};

